<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import { reactive } from 'vue';
import AppLayout from '../../layouts/AppLayout.vue';
import QuotationParticipants, { type Participant } from '../../components/QuotationParticipants.vue';
import { rupiah } from '../../composables/costing';
const props = defineProps<{ program: { id: number; nomor: string; judul: string; jenis: string; tgl_mulai: string; tgl_selesai: string; lokasi: string; target_peserta: number; closed_date: string | null }; quotations: { id: number; nomor: string; tanggal: string; berlaku_sampai: string; kepada_nama: string | null; name_customer: string | null; tujuan: string; up_nama: string | null; status: string; terisi: number; kuota_peserta: number; link_closed: string | null; calc: { grand_total: string; n_peserta: number } }[]; peserta: Participant[]; dataTab: boolean; filters: Record<string, string>; pesertaStatus: string; canAdd: boolean; canManage: boolean }>();
const f = reactive({ q: '', status: '', tujuan: '', data: props.dataTab ? 1 : 0, peserta_status: props.pesertaStatus, ...props.filters });
const search = () => router.get(`/quotation/batch/${props.program.id}`, f);
</script>
<template>
    <Head :title="program.nomor" /><AppLayout title="Quotation"><div class="page-head"><h1>{{ program.nomor }} · {{ program.judul }}</h1><Link v-if="canAdd && !dataTab" :href="`/quotation/create?id_penjualan=${program.id}`">Buat Quotation</Link></div><p>{{ program.jenis.toUpperCase() }} · {{ program.tgl_mulai }} s.d. {{ program.tgl_selesai }} · {{ program.lokasi }} · Target {{ program.target_peserta }} peserta{{ program.closed_date ? ' · Closed' : '' }}</p><Link href="/quotation">Semua Penjualan Program</Link>
        <nav class="form-actions" aria-label="Detail batch"><Link :href="`/quotation/batch/${program.id}`">Quotation</Link><Link :href="`/quotation/batch/${program.id}?data=1`">Data Peserta</Link><a v-if="dataTab && peserta.length" :href="`/quotation/batch/${program.id}/pdf`" target="_blank" rel="noopener">Export PDF peserta aktif dan surat</a></nav>
        <form class="filters" @submit.prevent="search"><label>Cari<input v-model="f.q" maxlength="100" type="search" /></label><label v-if="dataTab">Status peserta<select v-model="f.peserta_status"><option value="aktif">Aktif</option><option value="menunggu">Menunggu</option><option value="deal">Deal</option><option value="batal">Batal</option><option value="keluar">Keluar</option></select></label><template v-else><label>Status<select v-model="f.status"><option value="">Semua</option><option v-for="s in ['draft', 'terkirim', 'deal', 'batal']" :key="s">{{ s }}</option></select></label><label>Tujuan<select v-model="f.tujuan"><option value="">Semua</option><option value="personal">Personal</option><option value="company">Company</option></select></label></template><button class="primary">Terapkan</button></form>
        <QuotationParticipants v-if="dataTab" :rows="peserta" :manage="canManage && !program.closed_date" />
        <div v-else class="table-wrap"><table><thead><tr><th>Quotation</th><th>Kepada</th><th>Peserta</th><th>Nilai</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="q in quotations" :key="q.id"><td>{{ q.nomor }}<small>{{ q.tanggal }} · berlaku s.d. {{ q.berlaku_sampai }}</small></td><td>{{ q.name_customer || q.kepada_nama }}<small>{{ q.tujuan }} · {{ q.up_nama }}</small></td><td>{{ q.status === 'deal' ? `${q.calc.n_peserta} peserta Deal` : `${q.terisi} dari kuota ${q.kuota_peserta} terisi` }}</td><td>{{ rupiah(q.calc.grand_total) }}</td><td>{{ q.status }}<small>{{ q.link_closed || 'Link terbuka' }}</small></td><td><Link :href="`/quotation/${q.id}`">Lihat detail</Link><p><Link :href="`/quotation/${q.id}?tab=data`">Data Peserta</Link></p></td></tr><tr v-if="!quotations.length"><td colspan="6" class="empty">Belum ada quotation sesuai filter.</td></tr></tbody></table></div>
    </AppLayout>
</template>
